arguments.file_text:
@page "/courses"
@inject CatalogService Catalog

<PageTitle>Browse Courses</PageTitle>

<h1>Browse Courses</h1>
<p class="text-muted">Search and filter the Fall 2026 course offerings.</p>

<form method="get" action="courses" class="row g-3 mb-4">
    <div class="col-md-5">
        <label for="search" class="form-label">Search</label>
        <input type="text" class="form-control" id="search" name="search" value="@Search"
               placeholder="Course name, code, or instructor..." />
    </div>
    <div class="col-md-3">
        <label for="department" class="form-label">Department</label>
        <select class="form-select" id="department" name="department">
            <option value="">All Departments</option>
            @foreach (var dept in Catalog.GetDepartments())
            {
                <option value="@dept.Id" selected="@(Department == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <label for="credits" class="form-label">Credits</label>
        <select class="form-select" id="credits" name="credits">
            <option value="">Any</option>
            @foreach (var c in Catalog.GetAvailableCreditValues())
            {
                <option value="@c" selected="@(Credits == c)">@c</option>
            }
        </select>
    </div>
    <div class="col-md-2 d-flex align-items-end gap-2">
        <button type="submit" class="btn btn-primary">Filter</button>
        <a href="courses" class="btn btn-outline-secondary">Clear</a>
    </div>
</form>

@{
    var courses = Catalog.GetCourses(Department, Search, Credits);
}

<p class="text-muted mb-3">Showing @courses.Count course(s)</p>

@if (courses.Count == 0)
{
    <div class="alert alert-info">No courses match your search criteria. Try adjusting the filters.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Instructor</th>
                    <th>Credits</th>
                    <th>Schedule</th>
                    <th>Enrollment</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in courses)
                {
                    <tr>
                        <td><strong>@course.CourseCode</strong></td>
                        <td>@course.Title</td>
                        <td>@course.Instructor.Name</td>
                        <td>@course.Credits</td>
                        <td>@course.Schedule</td>
                        <td>
                            <span class="badge @(course.CurrentEnrollment >= course.MaxEnrollment ? "bg-danger" : "bg-success")">
                                @course.CurrentEnrollment / @course.MaxEnrollment
                            </span>
                        </td>
                        <td><a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public string? Department { get; set; }
    [SupplyParameterFromQuery] public int? Credits { get; set; }
}

@page "/enroll"
@inject CatalogService Catalog

<PageTitle>Request Enrollment</PageTitle>

<h1>Request Enrollment</h1>
<p class="text-muted">Submit your enrollment request for a Fall 2026 course. All fields marked with * are required.</p>

@if (Submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Enrollment Request Submitted</h4>
        <p>
            Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for
            <strong>@(Catalog.GetCourse(Model.CourseId)?.Title ?? Model.CourseId)</strong>
            has been received.
        </p>
        <hr />
        <p class="mb-0">You will receive a confirmation at <strong>@Model.Email</strong> once your request is processed.</p>
    </div>
    <a href="enroll" class="btn btn-primary">Submit Another Request</a>
    <a href="courses" class="btn btn-outline-secondary ms-2">Browse Courses</a>
}
else
{
    <EditForm method="post" Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment" Enhance>
        <DataAnnotationsValidator />
        <AntiforgeryToken />
        <ValidationSummary class="text-danger mb-3" />

        <div class="row">
            <div class="col-md-6 mb-3">
                <label for="studentName" class="form-label">Full Name *</label>
                <InputText id="studentName" class="form-control" @bind-Value="Model.StudentName" />
                <ValidationMessage For="() => Model.StudentName" class="text-danger" />
            </div>

            <div class="col-md-6 mb-3">
                <label for="studentId" class="form-label">Student ID *</label>
                <InputText id="studentId" class="form-control" @bind-Value="Model.StudentId"
                           placeholder="e.g., CS123456" />
                <ValidationMessage For="() => Model.StudentId" class="text-danger" />
            </div>
        </div>

        <div class="row">
            <div class="col-md-6 mb-3">
                <label for="email" class="form-label">Email</label>
                <InputText id="email" class="form-control" @bind-Value="Model.Email"
                           placeholder="student@university.edu" />
                <ValidationMessage For="() => Model.Email" class="text-danger" />
            </div>

            <div class="col-md-6 mb-3">
                <label for="courseId" class="form-label">Course *</label>
                <InputSelect id="courseId" class="form-select" @bind-Value="Model.CourseId">
                    <option value="">— Select a course —</option>
                    @foreach (var course in Catalog.GetCourses())
                    {
                        <option value="@course.Id">@course.CourseCode — @course.Title (@course.Credits cr)</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.CourseId" class="text-danger" />
            </div>
        </div>

        <div class="mb-3">
            <label for="comments" class="form-label">Comments</label>
            <InputTextArea id="comments" class="form-control" @bind-Value="Model.Comments" rows="3"
                           placeholder="Any additional information..." />
        </div>

        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
        <a href="courses" class="btn btn-outline-secondary ms-2">Cancel</a>
    </EditForm>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public string? CourseId { get; set; }

    private bool Submitted { get; set; }

    protected override void OnInitialized()
    {
        if (!string.IsNullOrEmpty(CourseId) && string.IsNullOrEmpty(Model.CourseId))
        {
            Model.CourseId = CourseId;
        }
    }

    private void HandleSubmit()
    {
        Submitted = true;
    }
}

